def apply_repairs():
    import faithful_part1
    import faithful_part2
    import faithful_part3
    import faithful_part4

    parts = [
        ('faithful_part1.py', 'PART_1', faithful_part1.PART_1),
        ('faithful_part2.py', 'PART_2', faithful_part2.PART_2),
        ('faithful_part3.py', 'PART_3', faithful_part3.PART_3),
        ('faithful_part4.py', 'PART_4', faithful_part4.PART_4),
    ]

    repaired_count = 0
    for filename, part_var_name, part_data in parts:
        filepath = f"/Users/Business(C)/shoonaya-mobile/scripts/{filename}"
        new_part_data = []
        for row in part_data:
            slug = row['slug']
            if slug in REPAIRED_TRANSLATIONS:
                new_part_data.append(REPAIRED_TRANSLATIONS[slug])
                repaired_count += 1
                print(f"Repaired: {slug} in {filename}")
            else:
                new_part_data.append(row)
        
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write("# -*- coding: utf-8 -*-\n\n")
            f.write(f"{part_var_name} = ")
            f.write(json.dumps(new_part_data, ensure_ascii=False, indent=4))
            f.write("\n")
        print(f"Wrote {len(new_part_data)} rows to {filepath}")

    print(f"\nTotal slugs repaired: {repaired_count} / {len(REPAIRED_TRANSLATIONS)}")
    assert repaired_count == 28, f"Expected 28 repaired slugs, got {repaired_count}"

if __name__ == '__main__':
    apply_repairs()
